Existing slide JSON:
{
 "slides": [
 {
 "title": "Introduction to Viscosity Law",
 "bullets": [
 "Defining viscosity: fluid's resistance to flow.",
 "Viscosity is an intrinsic fluid property.",
 "Relates shear stress to shear rate.",
 "Key concept in fluid dynamics study."
 ],
 "notes": "Introduce viscosity as internal friction within a fluid, setting the stage for the quantitative laws governing it."
 },
 {
 "title": "Newton's Law of Viscosity",
 "bullets": [
 "Formulated by Sir Isaac Newton (1687).",
 "Applies to Newtonian fluids.",
 "Shear stress proportional to velocity gradient.",
 "Mathematical expression: $\\tau = \\mu \\frac{du}{dy}$."
 ],
 "images": [
 {"id": "newtonviscosity", "caption": "Diagram illustrating shear stress in a fluid layer."}
 ],
 "notes": "Focus on the direct proportionality and introduce the viscosity coefficient, $\\mu$ (dynamic viscosity)."
 },
 {
 "title": "Components of Newton's Law",
 "bullets": [
 "$\\tau$ is the shear stress (Force/Area).",
 "$\\mu$ is the dynamic viscosity coefficient.",
 "$\\frac{du}{dy}$ is the shear rate or velocity gradient.",
 "Units of $\\mu$: Pascal-second (Pa·s) or Poise."
 ],
 "notes": "Detail the physical meaning and standard SI units for each variable in the fundamental equation."
 },
 {
 "title": "Velocity Gradient in Parallel Plates",
 "bullets": [
 "Consider two parallel plates.",
 "Lower plate stationary, upper plate moving.",
 "Linear velocity profile assumed.",
 "Shear rate calculation based on plate separation."
 ],
 "images": [
 {"id": "couetteflow", "caption": "Schematic of Couette flow between parallel plates."}
 ],
 "notes": "Use the classic Couette flow model to visualize and simplify the calculation of the velocity gradient $\\frac{du}{dy}$."
 },
 {
 "title": "Newtonian vs. Non-Newtonian Fluids",
 "bullets": [
 "Newtonian fluids follow the simple linear law.",
 "Viscosity remains constant under varying shear.",
 "Examples: Water, air, simple oils.",
 "Non-Newtonian fluids show variable viscosity."
 ],
 "notes": "Contrast the behavior. Newtonian fluids are the ideal case where viscosity is independent of the rate of deformation."
 },
 {
 "title": "Non-Newtonian Fluid Behavior",
 "bullets": [
 "Shear-thinning (Pseudoplastic): viscosity decreases.",
 "Shear-thickening (Dilatant): viscosity increases.",
 "Bingham plastics require yield stress to flow.",
 "Complex constitutive equations needed."
 ],
 "images": [
 {"id": "nonnewtoniancurves", "caption": "Comparison of shear stress vs. shear rate curves."}
 ],
 "notes": "Briefly introduce the categories of non-Newtonian fluids to show the limitations of Newton's simple law."
 },
 {
 "title": "Stokes' Law of Viscous Drag",
 "bullets": [
 "Applies to slow, laminar flow around spheres.",
 "Relates drag force to fluid viscosity.",
 "Formula: $Fd = 6\\pi \\mu r v$.",
 "Valid for very small Reynolds numbers."
 ],
 "notes": "Transition to a specific application of viscosity law concerning objects moving through fluids, introducing Stokes' Law."
 },
 {
 "title": "Terminal Velocity and Stokes' Law",
 "bullets": [
 "Terminal velocity achieved when drag equals gravity.",
 "Used to determine particle size or fluid viscosity.",
 "Balance between gravitational and viscous forces.",
 "Crucial in sedimentation analysis."
 ],
 "images": [
 {"id": "fallingsphere", "caption": "A sphere falling through a viscous liquid reaching terminal velocity."}
 ],
 "notes": "Explain how terminal velocity ($v_t$) is derived by equating the buoyant/gravitational force with the Stokes' drag force."
 },
 {
 "title": "Factors Affecting Dynamic Viscosity",
 "bullets": [
 "Temperature significantly impacts viscosity.",
 "Liquids: viscosity decreases as temperature rises.",
 "Gases: viscosity increases as temperature rises.",
 "Pressure effects are usually negligible for liquids."
 ],
 "notes": "Discuss the thermodynamic dependence. The mechanism of momentum transfer differs between liquids (cohesive forces) and gases (molecular collisions)."
 },
 {
 "title": "Kinematic Viscosity ($\\nu$)",
 "bullets": [
 "Ratio of dynamic viscosity to fluid density.",
 "Formula: $\\nu = \\mu / \\rho$.",
 "Represents viscous diffusion rate.",
 "Units: square meters per second (m$^2$/s)."
 ],
 "notes": "Introduce kinematic viscosity as a secondary, but important, measure, particularly in flow analysis where inertial effects are balanced against viscous effects (Reynolds number context)."
 }
 ]
}

